RModel RPiezoExperimentService::templateCandidate(const RModel &source,const QJsonObject &a) {
    if(a["kind"].toString()=="solidHex"||a["kind"].toString()=="solidTet")return RPiezoSolidRecipe::templateCandidate(source,a);
    if(a["kind"].toString()=="axialTruss")return RPiezoAxialExperimentService::templateCandidate(source,a);
    require(source.getNNodes()==0&&source.getNElements()==0,"Templates require an empty model");keys(a,{"kind","length","width","thickness","elements"});int kind=choice(a["kind"],{"cantileverBeam","flatPlate"});double length=number(a["length"]),width=number(a["width"]),thickness=number(a["thickness"]);uint count=integer(a["elements"]);require(length>0&&width>0&&thickness>0&&count>0&&count<=100,"Invalid template dimensions or count");RModel m=source;
    for(uint i=0;i<=count;++i){m.addNode(RNode(length*i/count,0,0));if(kind)m.addNode(RNode(length*i/count,width,0));}
    for(uint i=0;i<count;++i){RElement e(kind?R_ELEMENT_QUAD1:R_ELEMENT_BEAM1);if(kind){e.setNodeId(0,2*i);e.setNodeId(1,2*i+2);e.setNodeId(2,2*i+3);e.setNodeId(3,2*i+1);}else{e.setNodeId(0,i);e.setNodeId(1,i+1);}m.addElement(e,true,0);}return m;
}

