        const auto mask=source.getProblemTaskTree().getProblemTypeMask();require((mask&~(R_PROBLEM_STRESS|R_PROBLEM_STRESS_MODAL))==0,"Unsupported source analysis");
        bool replace=r.contains("replaceLegacyConditions")?boolean(r["replaceLegacyConditions"]):false;auto removed=legacy(candidate,false);require(removed.isEmpty()||replace,"Legacy conditions require explicit replaceLegacyConditions=true; all old loads/supports will be replaced");if(replace)legacy(candidate,true);
        auto &p=candidate.getProblemSetup();p.setRestart(false);p.setStructuralDynamicsRestartData({});p.setStructuralTrussDynamicsRestartData({});p.setStructuralPiezoLayeredRestart({});p.getStructuralNativeControlState()={};
        candidate.clearResults();candidate.clearEntityVariableData();RProblemTaskItem task;task.setNIterations(1);task.addChild(RProblemTaskItem(R_PROBLEM_STRESS));candidate.setProblemTaskTree(task);p.setMassMatrixType(RMassMatrixType::Consistent);p.getStructuralDynamicsSetup()={};auto &d=p.getStructuralDynamicsSetup();d.setEnabled(true);d.setTimeStep(dt);d.setNSteps(steps);
        double start=source.getTimeSolver().getInputStartTime();require(std::isfinite(start),"Nonfinite source clock");double initial=start-dt;require(std::isfinite(initial),"Invalid initial time");std::vector<double> times;for(uint i=0;i<steps;++i){double t=initial+double(i+1)*dt;require(std::isfinite(t)&&(times.empty()||t>times.back()),"Integration clock cannot represent requested grid");times.push_back(t);}candidate.getTimeSolver().setTimes(times);candidate.getTimeSolver().setInputStartTime(start);candidate.getTimeSolver().setInputNTimeSteps(steps);candidate.getTimeSolver().setInputTimeStepSize(dt);candidate.getTimeSolver().setCurrentTimeStep(0);candidate.getTimeSolver().setComputedTime(initial);
        setup.bindToModel(candidate);p.getStructuralPiezoLayeredSetup()=setup;setup.validate(candidate);
        const bool modal=setup.damping.kind==RStructuralPiezoDampingKind::UniformModal||setup.damping.kind==RStructuralPiezoDampingKind::PerMode||setup.damping.kind==RStructuralPiezoDampingKind::PerCluster;auto preliminary=setup;if(modal){preliminary.damping={};preliminary.sourceFingerprint.clear();}
