        std::set<uint> physical;for(uint i=0;i<candidate.getNNodes();++i)physical.insert(candidate.getNodePhysicalId(i));for(auto v:r["design"].toObject()["outputs"].toArray())require(physical.count(integer(v.toObject()["physicalNodeId"])),"Unknown design output node");
        for(auto v:RPiezoExperimentDeclarations::forceChannels(object(r["excitation"]))){auto o=object(v);auto parts=string(o["channelId"]).split(':');uint id=parts[1].toUInt();auto node=std::find(adapter.mesh().nodeIds.begin(),adapter.mesh().nodeIds.end(),id);require(node!=adapter.mesh().nodeIds.end(),"Unknown excitation physical node");const auto nodal=RPiezoExperimentDeclarations::forceDirection(o,string(r["family"]),setup.frame);std::vector<double> direction(6*adapter.mesh().nodeIds.size(),0);std::copy(nodal.begin(),nodal.end(),direction.begin()+6*size_t(node-adapter.mesh().nodeIds.begin()));adapter.mesh().projectPhysical(direction,RStructuralPiezoPhysicalDomain::ForceAndMoment);}
        auto control=r["controller"].toObject();if(control["kind"].toString()=="discrete_state_space"){uint every=control.contains("controlEveryFESteps")?integer(control["controlEveryFESteps"]):1;require(number(control["samplingPeriod"])==dt*every,"Controller samplingPeriod differs from FE control period");}
        result.candidate=std::move(candidate);result.valid=true;result.code="ok";result.message="Whole experiment preview compiled";result.normalizedArguments=r;result.normalizedArguments["replaceLegacyConditions"]=replace;result.units=si();result.invalidation={{"results",true},{"restart",true},{"modes",true},{"rom",true},{"controllerGains",true},{"approval",true}};
        for(auto it=r.begin();it!=r.end();++it)result.changedPaths.append("/"+it.key());result.changedPaths.append("/problemSetup");result.changedPaths.append("/results");result.changedPaths.append("/timeSolver");
        QJsonArray ports;for(const auto &port:setup.ports)ports.append(QJsonObject{{"portId",port.readout.portId},{"role",int(port.readout.role)},{"readout",int(port.readout.readout)},{"unit",rStructuralPiezoReadoutUnit(port.readout.readout)}});
