        QJsonArray materials;for(const auto &m:s.materials)materials.append(QJsonObject{{"materialId",m.materialId},{"form",m.form==RStructuralPiezoMaterialForm::StressCharge?"stressCharge":"strainCharge"},{"elasticityOrCompliance",json(m.elasticityOrCompliance)},{"coupling",json(m.coupling)},{"permittivity",json(m.permittivity)},{"density",m.density},{"piezoelectric",m.piezoelectric},{"sourceKind",m.sourceKind==RStructuralPiezoMaterialSourceKind::Example?"example":m.sourceKind==RStructuralPiezoMaterialSourceKind::Vendor?"vendor":"calibration"},{"sourceId",m.sourceId},{"sourceSha256",m.sourceSha256},{"notes",m.notes}});r["materials"]=materials;
        QJsonArray members;for(const auto &m:s.members){QJsonArray layers;for(const auto &l:m.layers)layers.append(QJsonObject{{"materialId",l.materialId},{"lowerZ",l.lowerZ},{"upperZ",l.upperZ},{"width",l.width},{"portId",l.portId},{"polarity",l.polarity},{"coverage",json(l.coverage)}});members.append(QJsonObject{{"physicalElementId",double(m.physicalElementId)},{"layers",layers}});}r["members"]=members;
        const char *roles[]={"actuator","sensor","actuatorSensor"},*readouts[]={"none","openCircuitVoltage","shortCircuitCharge","idealChargeAmplifier","actuatorCharge"},*dofs[]={"UX","UY","UZ","RX","RY","RZ"},*damping[]={"none","rayleigh","uniformModal","perMode","perCluster","imported"};QJsonArray ports;for(const auto &p:s.ports)ports.append(QJsonObject{{"portId",p.readout.portId},{"role",roles[int(p.readout.role)]},{"readout",readouts[int(p.readout.readout)]},{"initialValue",p.initialValue},{"Cf",p.readout.Cf},{"amplifierPolarity",p.readout.amplifierPolarity},{"Qref",p.readout.Qref},{"VoutBias",p.readout.VoutBias}});r["ports"]=ports;
