        QJsonArray wn,wp;for(const auto &n:s.workpoint.nodes)wn.append(QJsonObject{{"physicalNodeId",double(n.physicalNodeId)},{"q0",json(n.q0)},{"f0",json(n.f0)}});for(const auto &p:s.workpoint.ports)wp.append(QJsonObject{{"portId",p.portId},{"V0",p.V0},{"Q0",p.Q0}});r["workpoint"]=QJsonObject{{"available",s.workpoint.available},{"nodes",wn},{"ports",wp}};
